"""Offline geometric/partition checks; these are not field-accuracy measurements."""

import tempfile
import unittest
from pathlib import Path

from affine import Affine
from pyproj import CRS

from pipeline.geo import box_center_to_wgs84, neatline_polygon, pixel_to_wgs84
from pipeline.prepare_dataset import prepare, spatial_split, verify_no_cross_split_overlap


class CoordinatesTest(unittest.TestCase):
    def test_three_independent_web_mercator_reference_points(self):
        # Known spherical Mercator reference values, not values generated by our helper.
        wkt = CRS.from_epsg(3857).to_wkt()
        for x,y,lon,lat in [(0,0,0,0),(111319.49079327357,0,1,0),
                            (0,111325.1428663851,0,1)]:
            point = pixel_to_wgs84([1,0,0,0,1,0],wkt,x,y)
            self.assertAlmostEqual(point["lon"],lon,places=7)
            self.assertAlmostEqual(point["lat"],lat,places=7)

    def test_box_uses_pixel_edges_without_an_extra_half_pixel(self):
        tile = {"transform":[.001,0,-119,0,-.001,35.5],
                "crs":CRS.from_epsg(4326).to_wkt(),"widthPx":1024,"heightPx":1024}
        actual = box_center_to_wgs84(tile,{"x":10,"y":20,"w":8,"h":10})
        self.assertAlmostEqual(actual["lon"],-118.986)
        self.assertAlmostEqual(actual["lat"],35.475)

    def test_rotation_and_shear_are_preserved(self):
        actual = pixel_to_wgs84([.001,.0001,-119,.0002,-.001,35.5],
            CRS.from_epsg(4326).to_wkt(),10,20)
        self.assertAlmostEqual(actual["lon"],-118.988)
        self.assertAlmostEqual(actual["lat"],35.482)

    def test_nonfinite_and_malformed_inputs_rejected(self):
        for affine in [[1,2],[1,0,float("nan"),0,1,0]]:
            with self.assertRaises(ValueError):
                pixel_to_wgs84(affine,CRS.from_epsg(4326).to_wkt(),0,0)

    def test_out_of_tile_box_rejected(self):
        tile = {"transform":[1,0,0,0,1,0],"crs":CRS.from_epsg(4326).to_wkt(),
                "widthPx":1024,"heightPx":1024}
        for box in [{"x":1020,"y":0,"w":10,"h":10},
                    {"x":0,"y":0,"w":0,"h":10}]:
            with self.assertRaises(ValueError):
                box_center_to_wgs84(tile,box)

    def test_nominal_neatline_stays_in_source_datum(self):
        polygon = neatline_polygon(CRS.from_epsg(4267).to_wkt(),[-119,35.375,-118.875,35.5])
        self.assertEqual(tuple(polygon["coordinates"][0][0]),(-119,35.375))

    def test_window_affine_keeps_source_corner_positions(self):
        source = Affine(2,.3,100,.1,-2,500)
        window = source*Affine.translation(819,1638)
        for x,y in [(0,0),(1024,0),(0,1024),(1024,1024)]:
            actual = ~source*(window*(x,y))
            self.assertAlmostEqual(actual[0],819+x)
            self.assertAlmostEqual(actual[1],1638+y)


def synthetic_tiles():
    rows = []
    # Two years at quad zero overlap almost completely, like the actual sources.
    for sheet,(year,quad) in enumerate([(1954,0),(1954,1),(1992,0)]):
        for y in range(8):
            for x in range(8):
                left = quad*7000+x*819+sheet*.5
                bottom = y*819+sheet*.5
                rows.append({"tileId":f"{sheet}-{x}-{y}","mapYear":year,
                             "split_bounds_m":[left,bottom,left+1024,bottom+1024]})
    return rows


class PartitionTest(unittest.TestCase):
    def test_repeatable_with_thirty_test_tiles_and_quarantined_boundaries(self):
        tiles = synthetic_tiles()
        first,bounds = spatial_split(tiles)
        self.assertEqual((first,bounds),spatial_split(tiles))
        self.assertGreaterEqual(sum(s=="test" for s in first.values()),30)
        self.assertGreater(sum(s=="buffer" for s in first.values()),0)
        for tile in tiles:
            tile["split"] = first[tile["tileId"]]
        verify_no_cross_split_overlap(tiles)
        for split in ["train","val","test"]:
            self.assertEqual({t["mapYear"] for t in tiles if t["split"]==split},{1954,1992})

    def test_overlapping_cross_year_images_are_rejected(self):
        tiles = synthetic_tiles()
        a,b = dict(tiles[0],split="train"),dict(tiles[128],split="test")
        with self.assertRaisesRegex(ValueError,"Spatial leakage"):
            verify_no_cross_split_overlap([a,b])

    def test_too_small_dataset_cannot_silently_shrink_test_requirement(self):
        with self.assertRaises(ValueError):
            spatial_split(synthetic_tiles()[:10])

    def test_existing_dataset_is_not_overwritten(self):
        with tempfile.TemporaryDirectory() as folder:
            with self.assertRaises(FileExistsError):
                prepare(Path("missing"),Path("missing"),Path("missing"),Path(folder))


if __name__ == "__main__":
    unittest.main()
